use vstd::prelude::*;

verus! {

    /// Return the minimum element of a non‐empty vector of i8’s.
    /// 
    /// # Requirements
    /// * `a.len() > 0`
    /// 
    /// # Post‐conditions
    /// * The returned `result` is equal to some entry of `a`.
    /// * `result` is less than or equal to every element of `a`.
    fn nanmin(a: Vec<i8>) -> (result: i8)
        requires
            a.len() > 0,
        ensures
            // result is one of the elements of a
            exists |j: usize| j < a.len() && result == a[j],
        ensures
            // result is ≤ every element of a
            forall |k: usize| k < a.len() ==> result <= a[k],
    {
        // Initialize the running minimum to the first element
        let mut min: i8 = a[0];
        // We'll scan from index 1 up to a.len()
        let mut i: usize = 1;
        let n = a.len();

        // Loop invariant keeps track that `min` is the minimum
        // over the prefix a[0..i):
        //  1) for all k < i, min ≤ a[k]
        //  2) there is some j < i with a[j] = min
        while i < n
            invariant
                i <= n,
            invariant
                forall |k: usize| k < i ==> min <= a[k],
            invariant
                exists |j: usize| j < i && min == a[j],
            decreases
                n - i,
        {
            let x = a[i];
            if x < min {
                min = x;
            }
            i += 1;
        }

        // At this point i == n, so the invariants tell us
        // min is the minimum of the entire array.
        result = min;
    }

}